class Solution {long cross(int[] a,int[] b,int[] c){return ((long)b[0]-a[0])*((long)c[1]-a[1])-((long)b[1]-a[1])*((long)c[0]-a[0]);}boolean on(int[] p,int[] a,int[] b){return p[0]>=Math.min(a[0],b[0])&&p[0]<=Math.max(a[0],b[0])&&p[1]>=Math.min(a[1],b[1])&&p[1]<=Math.max(a[1],b[1]);}public boolean solve(int[][] first,int[][] second){int[] a=first[0],b=first[1],c=second[0],d=second[1];long p=cross(a,b,c),q=cross(a,b,d),r=cross(c,d,a),s=cross(c,d,b);if(p==0&&on(c,a,b)||q==0&&on(d,a,b)||r==0&&on(a,c,d)||s==0&&on(b,c,d))return true;return (p<0&&q>0||p>0&&q<0)&&(r<0&&s>0||r>0&&s<0);}}